package ir.orix.school.assessment.domain;
import java.math.BigDecimal; import jakarta.persistence.*; import ir.orix.school.organization.domain.Tenant; import ir.orix.school.shared.persistence.AuditedEntity;
@Entity @Table(name="assessment_question",schema="school")
public class AssessmentQuestion extends AuditedEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_id") private Assessment assessment; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="section_id") private AssessmentSection section; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="question_version_id") private QuestionVersion questionVersion; @Column(nullable=false,precision=10,scale=2) private BigDecimal points; @Column(name="sequence_number",nullable=false) private int sequenceNumber; protected AssessmentQuestion(){} public AssessmentQuestion(Tenant tenant,Assessment assessment,AssessmentSection section,QuestionVersion version,BigDecimal points,int sequence){this.tenant=tenant;this.assessment=assessment;this.section=section;this.questionVersion=version;this.points=points;this.sequenceNumber=sequence;} public Assessment getAssessment(){return assessment;} public AssessmentSection getSection(){return section;} public QuestionVersion getQuestionVersion(){return questionVersion;} public BigDecimal getPoints(){return points;} public int getSequenceNumber(){return sequenceNumber;} }
